@@
 export const canary = true;
+
+export function greet(name: string): string {
+  return `Hello, ${name}!`;
+}
*** Add File: tests/canary.test.ts
+import { expect, test } from "bun:test";
+import { greet } from "../src/canary";
+
+test("greets Ada", () => {
+  expect(greet("Ada")).toBe("Hello, Ada!");
+});
+
+test("greets Grace", () => {
+  expect(greet("Grace")).toBe("Hello, Grace!");
+});
*** End Patch

